function inspoOnbodyIngest(j) {
  if (!j || !Array.isArray(j.looks)) return false;
  var ok = j.looks.filter(function (l) { return l && l.id && l.f && /^[A-Za-z0-9._-]+$/.test(l.f); });
  if (ok.length < INSPO_ONBODY.looks.length) return false;
  INSPO_ONBODY.looks = ok;
  return true;
}
